using System.Reflection;
using System.Text.Json;

namespace Quartermaster.Documents;

/// <summary>One tessdata_fast language: its code, English name, and the size and SHA-256 a download must match.</summary>
public sealed record OcrLanguageEntry(string Code, string Name, long Bytes, string Sha256, bool Bundled);

/// <summary>The pinned tessdata_fast 4.1.0 catalog, loaded once from the embedded JSON (generated by build/ocr-catalog.ps1).</summary>
public static class OcrLanguageCatalog
{
    public const string Tag = "4.1.0";
    private const string BundledCode = "eng";
    private const string ResourceName = "Quartermaster.Documents.Ocr.tessdata-fast-4.1.0.json";

    private static readonly Lazy<(IReadOnlyList<OcrLanguageEntry> List, Dictionary<string, OcrLanguageEntry> ByCode)> Loaded = new(Load);

    public static IReadOnlyList<OcrLanguageEntry> Entries => Loaded.Value.List;

    public static OcrLanguageEntry? Find(string code) =>
        code is not null && Loaded.Value.ByCode.TryGetValue(code, out var e) ? e : null;

    public static string Url(string code) =>
        $"https://raw.githubusercontent.com/tesseract-ocr/tessdata_fast/{Tag}/{code}.traineddata";

    private static (IReadOnlyList<OcrLanguageEntry>, Dictionary<string, OcrLanguageEntry>) Load()
    {
        using var stream = typeof(OcrLanguageCatalog).Assembly.GetManifestResourceStream(ResourceName)
            ?? throw new InvalidOperationException("Embedded OCR catalog is missing.");
        using var doc = JsonDocument.Parse(stream);
        var list = new List<OcrLanguageEntry>();
        foreach (var l in doc.RootElement.GetProperty("languages").EnumerateArray())
        {
            var code = l.GetProperty("code").GetString()!;
            list.Add(new OcrLanguageEntry(code, l.GetProperty("name").GetString()!, l.GetProperty("bytes").GetInt64(),
                l.GetProperty("sha256").GetString()!, code == BundledCode));
        }
        return (list, list.ToDictionary(e => e.Code, StringComparer.OrdinalIgnoreCase));
    }
}
